#include <iostream>
#include <vector>
#include <queue>
#include <cmath>
#include <iomanip>
#include <cassert>
#include <algorithm>
#include <climits>
using namespace std;

using ll = long long;
using pii = pair<int, int>;
using vi = vector<int>;

const int T = 99;
const int C = 12;
const ll INF = 0x3f3f3f3f3f3f3f3fLL;

struct Edge {
    int to, reverse;
    ll flow, capacity, cost;
};

class MinCostFlow {
public:
    int nodes;
    vector<vector<Edge>> graph;
    vector<ll> dist, pot;
    vector<int> par_node, par_edge;
    vector<bool> visited;

    MinCostFlow(int n) : nodes(n), graph(n), dist(n, INF), pot(n, 0),
                         par_node(n), par_edge(n), visited(n, false) {}

    void addEdge(int from, int to, ll cap, ll cost) {
        graph[from].emplace_back(Edge{to, (int)graph[to].size(), 0, cap, cost});
        graph[to].emplace_back(Edge{from, (int)graph[from].size()-1, 0, 0, -cost});
    }

    bool dijkstra(int src, int dst, ll lb) {
        fill(dist.begin(), dist.end(), INF);
        fill(visited.begin(), visited.end(), false);
        dist[src] = 0;
        priority_queue<pair<ll, int>, vector<pair<ll, int>>, greater<pair<ll, int>>> pq;
        pq.emplace(0, src);

        while (!pq.empty()) {
            auto [d, u] = pq.top(); pq.pop();
            if (visited[u]) continue;
            visited[u] = true;
            for (int i = 0; i < graph[u].size(); ++i) {
                auto& e = graph[u][i];
                if (e.flow <= e.capacity - lb && dist[e.to] > dist[u] + pot[u] - pot[e.to] + e.cost) {
                    dist[e.to] = dist[u] + pot[u] - pot[e.to] + e.cost;
                    par_node[e.to] = u;
                    par_edge[e.to] = i;
                    pq.emplace(dist[e.to], e.to);
                }
            }
        }
        return dist[dst] < INF;
    }

    pair<ll, ll> augment(int src, int dst) {
        ll flow = INF;
        for (int v = dst; v != src; v = par_node[v]) {
            auto& e = graph[par_node[v]][par_edge[v]];
            flow = min(flow, e.capacity - e.flow);
        }
        ll cost = 0;
        for (int v = dst; v != src; v = par_node[v]) {
            auto& e = graph[par_node[v]][par_edge[v]];
            e.flow += flow;
            graph[v][e.reverse].flow -= flow;
            cost += flow * graph[v][e.reverse].cost;
        }
        for (int i = 0; i < nodes; ++i) {
            if (dist[i] < INF) pot[i] += dist[i];
        }
        return {flow, cost};
    }

    ll compute(int src, int dst, ll& totalCost) {
        totalCost = 0;
        ll totalFlow = 0;

        for (ll lb = 1LL << 30; lb > 0; lb >>= 1) {
            while (dijkstra(src, dst, lb)) {
                auto [df, dc] = augment(src, dst);
                totalFlow += df;
                totalCost += dc;
            }
        }
        return totalFlow;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cout << fixed << setprecision(10);

    int n, m, k, c, d;
    cin >> n >> m >> k >> c >> d;

    int source = 0;
    int sink = n * T + 1;
    MinCostFlow mcf(sink + 1);

    for (int i = 0; i < k; ++i) {
        int a;
        cin >> a;
        mcf.addEdge(source, a, 1, 0);
    }

    for (int t = 0; t < T; ++t) {
        mcf.addEdge(1 + t * n, sink, INF, 0);
        if (t > 0) {
            for (int i = 1; i <= n; ++i) {
                mcf.addEdge(i + (t - 1) * n, i + t * n, INF, c);
            }
        }
    }

    for (int i = 0; i < m; ++i) {
        int a, b;
        cin >> a >> b;
        for (int j = 0; j < C; ++j) {
            int cost = (j + 1) * (j + 1) - j * j;
            for (int t = 1; t < T; ++t) {
                mcf.addEdge(a + (t - 1) * n, b + t * n, 1, cost * d + c);
                mcf.addEdge(b + (t - 1) * n, a + t * n, 1, cost * d + c);
            }
        }
    }

    ll price;
    ll flow = mcf.compute(source, sink, price);
    assert(flow == k);
    cout << price << '\n';

    return 0;
}
